CREATE OR REPLACE FUNCTION public.yorisou_provisioning_stage_rank(p_stage text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_stage
    when 'account_creation'   then 1
    when 'canonical_identity' then 2
    when 'session_binding'    then 3
    when 'verification'       then 4
    when 'finalizing'         then 5
    when 'completed'          then 6
    else null end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_provisioning_stage_rank(p_stage text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_provisioning_stage_rank(p_stage text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_provisioning_stage_rank(p_stage text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_provisioning_stage_rank(p_stage text) to service_role';
  end if;
end $$;

