CREATE OR REPLACE FUNCTION public.yorisou_provisioning_status(p_provisioning_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'found', count(*) > 0,
    'state', max(state), 'cursor', max(provisioning_cursor),
    'accountId', max(account_id), 'failureClass', max(failure_class),
    'attemptCount', max(attempt_count), 'generation', max(executor_generation)
  )
  from public.yorisou_identity_provisioning_sagas
  where provisioning_key = p_provisioning_key;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_provisioning_status(p_provisioning_key text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_provisioning_status(p_provisioning_key text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_provisioning_status(p_provisioning_key text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_provisioning_status(p_provisioning_key text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_state_for_cursor(p_cursor text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_cursor
    when 'account_creation'   then 'requested'
    when 'canonical_identity' then 'account_created'
    when 'session_binding'    then 'canonical_identity_created'
    -- Verification is READ-ONLY, so reaching it changes nothing about what exists: both it and
    -- finalizing describe a saga whose session is bound and whose completeness is unproven.
    when 'verification'       then 'session_bound'
    when 'finalizing'         then 'session_bound'
    when 'completed'          then 'completed'
    else null end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_provisioning_state_for_cursor(p_cursor text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_provisioning_state_for_cursor(p_cursor text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_provisioning_state_for_cursor(p_cursor text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_provisioning_state_for_cursor(p_cursor text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_residue(p_account_id text DEFAULT NULL::text, p_owner_fingerprint text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::int from public.yorisou_identity_provisioning_sagas
   where (p_account_id is not null and account_id = p_account_id)
      or (p_owner_fingerprint is not null and owner_fingerprint = p_owner_fingerprint);
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_provisioning_residue(p_account_id text, p_owner_fingerprint text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_provisioning_residue(p_account_id text, p_owner_fingerprint text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_provisioning_residue(p_account_id text, p_owner_fingerprint text) from authenticated';
  end if;
