CREATE OR REPLACE FUNCTION public.yorisou_provisioning_open(p_provisioning_key text, p_token_hash text, p_ttl_seconds integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saga   public.yorisou_identity_provisioning_sagas%rowtype;
  v_locked boolean := false;
begin
  if p_provisioning_key is null or p_provisioning_key !~ '^[0-9a-f]{64}$' then
    raise exception 'provisioning_key_must_be_sha256_hex';
  end if;
  if p_token_hash is null or char_length(p_token_hash) < 32 then
    raise exception 'provisioning_executor_token_required';
  end if;
  if p_ttl_seconds is null or p_ttl_seconds < 5 or p_ttl_seconds > 600 then
    raise exception 'provisioning_executor_ttl_out_of_range';
  end if;

  -- Lock-or-create. The re-select after a lost insert race is not optional: `on conflict` returns no
  -- row, and proceeding without the lock is how two requests both believe they opened the saga.
  for i in 1..2 loop
    select * into v_saga from public.yorisou_identity_provisioning_sagas
     where provisioning_key = p_provisioning_key for update;
    if found then v_locked := true; exit; end if;
    begin
      insert into public.yorisou_identity_provisioning_sagas (provisioning_key) values (p_provisioning_key);
    exception when unique_violation then
      null;  -- a concurrent opener won; loop once more and LOCK its row
    end;
  end loop;
  if not v_locked then raise exception 'provisioning_saga_unavailable'; end if;

  -- Already done. A retry of a registration that succeeded is not a second registration; it is the
  -- same one, and it is finished. This is what makes "the response was lost" resolvable.
  if v_saga.state = 'completed' then
    return jsonb_build_object(
      'outcome', 'completed', 'claimed', false,
      'cursor', v_saga.provisioning_cursor, 'state', v_saga.state,
      'generation', v_saga.executor_generation, 'accountId', v_saga.account_id
    );
  end if;

  if v_saga.state = 'failed_terminal' then
    return jsonb_build_object(
      'outcome', 'failed_terminal', 'claimed', false,
      'cursor', v_saga.provisioning_cursor, 'state', v_saga.state,
      'failureClass', v_saga.failure_class, 'accountId', v_saga.account_id
    );
  end if;

  -- Someone else is driving and their claim has not lapsed. Two concurrent registrations for one
  -- email do not both proceed; the second is told the truth about why it is waiting.
  if v_saga.executor_token_hash is not null
     and v_saga.executor_token_hash <> p_token_hash
     and v_saga.executor_expires_at is not null
     and v_saga.executor_expires_at > now() then
    return jsonb_build_object(
      'outcome', 'in_progress', 'claimed', false,
      'cursor', v_saga.provisioning_cursor, 'state', v_saga.state,
      'generation', v_saga.executor_generation
    );
  end if;

  update public.yorisou_identity_provisioning_sagas
     set executor_token_hash = p_token_hash,
         executor_generation = v_saga.executor_generation + 1,
         executor_claimed_at = now(),
         executor_expires_at = now() + make_interval(secs => p_ttl_seconds),
         attempt_count       = v_saga.attempt_count + 1,
         -- A retryable failure is a note about the PREVIOUS attempt, never an instruction about
         -- where to start. The cursor is deliberately untouched.
         state               = case when v_saga.state = 'failed_retryable'
                                    then public.yorisou_provisioning_state_for_cursor(v_saga.provisioning_cursor)
                                    else v_saga.state end,
         updated_at          = now()
   where provisioning_key = p_provisioning_key;

  return jsonb_build_object(
    'outcome', 'claimed', 'claimed', true,
    'cursor', v_saga.provisioning_cursor,
    'state', public.yorisou_provisioning_state_for_cursor(v_saga.provisioning_cursor),
    'generation', v_saga.executor_generation + 1,
    'accountId', v_saga.account_id,
    'attemptCount', v_saga.attempt_count + 1,
    'resumed', v_saga.provisioning_cursor <> 'account_creation'
  );
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_provisioning_open(p_provisioning_key text, p_token_hash text, p_ttl_seconds integer) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_provisioning_open(p_provisioning_key text, p_token_hash text, p_ttl_seconds integer) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_provisioning_open(p_provisioning_key text, p_token_hash text, p_ttl_seconds integer) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_provisioning_open(p_provisioning_key text, p_token_hash text, p_ttl_seconds integer) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_complete_step(p_provisioning_key text, p_token_hash text, p_generation integer, p_expected_cursor text, p_next_cursor text, p_account_id text DEFAULT NULL::text, p_owner_fingerprint text DEFAULT NULL::text, p_session_fingerprint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saga public.yorisou_identity_provisioning_sagas%rowtype;
  v_next_state text;
begin
  select * into v_saga from public.yorisou_identity_provisioning_sagas
   where provisioning_key = p_provisioning_key for update;
  if not found then raise exception 'provisioning_saga_not_found'; end if;

  if v_saga.state in ('completed','failed_terminal') then
    raise exception 'provisioning_terminal_%', v_saga.state;
  end if;
  if v_saga.executor_token_hash is distinct from p_token_hash then
    raise exception 'provisioning_executor_mismatch';
  end if;
  if v_saga.executor_generation is distinct from p_generation then
    raise exception 'provisioning_executor_generation_stale';
  end if;
  if v_saga.provisioning_cursor is distinct from p_expected_cursor then
    raise exception 'provisioning_cursor_mismatch';
  end if;
  if public.yorisou_provisioning_stage_rank(p_next_cursor)
     is distinct from public.yorisou_provisioning_stage_rank(p_expected_cursor) + 1 then
    raise exception 'provisioning_cursor_illegal_transition';
  end if;

  -- The account binding is written once and is then immutable. A saga that changed which account it
  -- belonged to could bind a session to one account and complete another.
  if p_account_id is not null and v_saga.account_id is not null
     and v_saga.account_id is distinct from p_account_id then
    raise exception 'provisioning_account_rebind_refused';
  end if;

  v_next_state := public.yorisou_provisioning_state_for_cursor(p_next_cursor);

  update public.yorisou_identity_provisioning_sagas
     set provisioning_cursor = p_next_cursor,
         state               = v_next_state,
         account_id          = coalesce(v_saga.account_id, p_account_id),
         owner_fingerprint   = coalesce(v_saga.owner_fingerprint, p_owner_fingerprint),
         session_fingerprint = coalesce(p_session_fingerprint, v_saga.session_fingerprint),
         failure_class       = null,
         last_error_code     = null,
         completed_at        = case when v_next_state = 'completed' then now() else v_saga.completed_at end,
         updated_at          = now()
   where provisioning_key = p_provisioning_key;

  return jsonb_build_object(
    'cursor', p_next_cursor, 'state', v_next_state,
    'accountId', coalesce(v_saga.account_id, p_account_id)
  );
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_provisioning_complete_step(p_provisioning_key text, p_token_hash text, p_generation integer, p_expected_cursor text, p_next_cursor text, p_account_id text, p_owner_fingerprint text, p_session_fingerprint text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_provisioning_complete_step(p_provisioning_key text, p_token_hash text, p_generation integer, p_expected_cursor text, p_next_cursor text, p_account_id text, p_owner_fingerprint text, p_session_fingerprint text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_provisioning_complete_step(p_provisioning_key text, p_token_hash text, p_generation integer, p_expected_cursor text, p_next_cursor text, p_account_id text, p_owner_fingerprint text, p_session_fingerprint text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_provisioning_complete_step(p_provisioning_key text, p_token_hash text, p_generation integer, p_expected_cursor text, p_next_cursor text, p_account_id text, p_owner_fingerprint text, p_session_fingerprint text) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_abandon(p_provisioning_key text, p_token_hash text, p_generation integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_saga public.yorisou_identity_provisioning_sagas%rowtype; v_rows int;
begin
  select * into v_saga from public.yorisou_identity_provisioning_sagas
   where provisioning_key = p_provisioning_key for update;
  if not found then return false; end if;
  if v_saga.account_id is not null then
    raise exception 'provisioning_abandon_refused_account_bound';
  end if;
  if v_saga.executor_token_hash is distinct from p_token_hash
     or v_saga.executor_generation is distinct from p_generation then
    raise exception 'provisioning_executor_mismatch';
  end if;

  delete from public.yorisou_identity_provisioning_sagas
   where provisioning_key = p_provisioning_key and account_id is null;
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_provisioning_abandon(p_provisioning_key text, p_token_hash text, p_generation integer) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_provisioning_abandon(p_provisioning_key text, p_token_hash text, p_generation integer) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_provisioning_abandon(p_provisioning_key text, p_token_hash text, p_generation integer) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_provisioning_abandon(p_provisioning_key text, p_token_hash text, p_generation integer) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_identity_links_sync(p_owner_account_id text, p_owner_fingerprint text, p_links jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_link       jsonb;
  v_kind       text;
  v_digest     text;
  v_other      text;
  v_added      integer := 0;
  v_unchanged  integer := 0;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'identity_link_owner_required';
  end if;
  if p_owner_fingerprint is null or p_owner_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'identity_link_owner_fingerprint_must_be_sha256_hex';
  end if;
  if p_links is null or jsonb_typeof(p_links) <> 'array' then
    raise exception 'identity_link_set_must_be_array';
  end if;

  perform 1 from public.yorisou_canonical_identity_links
   where owner_account_id = p_owner_account_id and link_state = 'active'
   for update;

  -- Validate the whole set BEFORE writing any of it. A partially applied identity set is a state no
  -- reader has a name for.
  for v_link in select * from jsonb_array_elements(p_links) loop
    v_kind   := v_link->>'kind';
    v_digest := v_link->>'digest';
    if v_kind is null or v_digest is null then
      raise exception 'identity_link_entry_requires_kind_and_digest';
    end if;
    if v_kind not in ('email','line_subject','user_profile','auth_identity','provisioning') then
      raise exception 'identity_link_kind_unknown:%', v_kind;
    end if;
    if v_kind in ('email','line_subject') and v_digest !~ '^[0-9a-f]{64}$' then
      raise exception 'identity_link_digest_must_be_sha256_hex:%', v_kind;
    end if;

    select owner_account_id into v_other
      from public.yorisou_canonical_identity_links
     where link_kind = v_kind and link_digest = v_digest and link_state = 'active'
     for update;
    if v_other is not null and v_other <> p_owner_account_id then
      raise exception 'identity_link_conflict:%', v_kind;
    end if;
  end loop;

  -- NO RETIREMENT HERE. Deliberately. See the header: the caller's link set comes from a read that
  -- can be stale, and retiring on absence lets that stale read destroy a true record.
  for v_link in select * from jsonb_array_elements(p_links) loop
    v_kind   := v_link->>'kind';
    v_digest := v_link->>'digest';
    if exists (
      select 1 from public.yorisou_canonical_identity_links
       where link_kind = v_kind and link_digest = v_digest
         and link_state = 'active' and owner_account_id = p_owner_account_id
    ) then
      v_unchanged := v_unchanged + 1;
      continue;
    end if;
    begin
      insert into public.yorisou_canonical_identity_links
        (owner_account_id, owner_fingerprint, link_kind, link_digest)
      values (p_owner_account_id, p_owner_fingerprint, v_kind, v_digest);
      v_added := v_added + 1;
    exception when unique_violation then
      select owner_account_id into v_other
        from public.yorisou_canonical_identity_links
       where link_kind = v_kind and link_digest = v_digest and link_state = 'active';
      if v_other is distinct from p_owner_account_id then
        raise exception 'identity_link_conflict:%', v_kind;
      end if;
      v_unchanged := v_unchanged + 1;
    end;
  end loop;

  return jsonb_build_object(
    'added', v_added, 'retired', 0, 'unchanged', v_unchanged,
    'active', (select count(*) from public.yorisou_canonical_identity_links
                where owner_account_id = p_owner_account_id and link_state = 'active')
  );
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_identity_links_sync(p_owner_account_id text, p_owner_fingerprint text, p_links jsonb) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_identity_links_sync(p_owner_account_id text, p_owner_fingerprint text, p_links jsonb) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_identity_links_sync(p_owner_account_id text, p_owner_fingerprint text, p_links jsonb) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_identity_links_sync(p_owner_account_id text, p_owner_fingerprint text, p_links jsonb) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_identity_links_retire(p_owner_account_id text, p_link_kind text, p_link_digest text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner   text;
  v_retired integer := 0;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'identity_link_owner_required';
  end if;
  if p_link_kind is null or p_link_digest is null then
    raise exception 'identity_link_entry_requires_kind_and_digest';
  end if;

  select owner_account_id into v_owner
    from public.yorisou_canonical_identity_links
   where link_kind = p_link_kind and link_digest = p_link_digest and link_state = 'active'
   for update;

  if v_owner is null then return 0; end if;          -- already retired, or never held
  if v_owner <> p_owner_account_id then
    raise exception 'identity_link_conflict:%', p_link_kind;
  end if;

  update public.yorisou_canonical_identity_links
     set link_state = 'erased', owner_account_id = null, link_digest = null,
         erased_at = now(), updated_at = now()
   where link_kind = p_link_kind and link_digest = p_link_digest
     and link_state = 'active' and owner_account_id = p_owner_account_id;
  get diagnostics v_retired = row_count;
  return v_retired;
end $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_identity_links_retire(p_owner_account_id text, p_link_kind text, p_link_digest text) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_identity_links_retire(p_owner_account_id text, p_link_kind text, p_link_digest text) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_identity_links_retire(p_owner_account_id text, p_link_kind text, p_link_digest text) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_identity_links_retire(p_owner_account_id text, p_link_kind text, p_link_digest text) to service_role';
  end if;
end $$;

